(function(){"use strict";self.onmessage=async c=>{const{message:i,difficulty:f,offset:l=0,stride:d=1}=c.data,h="0".repeat(f),p=new TextEncoder,u=a=>Array.from(new Uint8Array(a)).map(n=>n.toString(16).padStart(2,"0")).join("");let e=l,o=0,s="f".repeat(64),r=0;for(;;){const a=p.encode(i+e),n=await crypto.subtle.digest("SHA-256",a),t=u(n);if(t<s&&(s=t,r=e),t.startsWith(h)){self.postMessage({type:"result",data:{nonce:e,hash:t}});break}e+=d,o++,o%1e3===0&&self.postMessage({type:"progress",data:{delta:1e3,hash:s,nonce:r}})}}})();
